export type PaneDirection = "horizontal" | "vertical";

export type PaneLeafNode = { type: "leaf"; leafId: string };

export type PaneSplitNode = {
  type: "split";
  direction: PaneDirection;
  first: PaneNode;
  second: PaneNode;
  ratio: number;
};

export type PaneNode = PaneLeafNode | PaneSplitNode;

export const MIN_PANE_RATIO = 0.1;
export const MAX_PANE_RATIO = 0.9;

/** Clamps a ratio into the usable range, falling back to an even split for non-finite input. */
export function clampRatio(ratio: number): number {
  if (!Number.isFinite(ratio)) return 0.5;
  return Math.min(MAX_PANE_RATIO, Math.max(MIN_PANE_RATIO, ratio));
}

export function createLeafNode(leafId?: string): PaneNode {
  return { type: "leaf", leafId: leafId ?? createLeafId() };
}

/**
 * Replaces the leaf `targetLeafId` with a split containing that leaf and a new leaf.
 * `position` decides which side the new leaf takes. Returns the original tree when
 * the target leaf does not exist.
 */
export function splitLeaf(
  root: PaneNode,
  targetLeafId: string,
  newLeafId: string,
  direction: PaneDirection,
  position: "first" | "second" = "second",
  ratio = 0.5,
): PaneNode {
  return splitLeafWithSubtree(root, targetLeafId, createLeafNode(newLeafId), direction, position, ratio);
}

/**
 * Replaces `targetLeafId` with a split containing the existing target leaf and an
 * arbitrary pane subtree. This is the pane-tree equivalent of Orca moving a whole
 * tab (including any terminal panes owned by that tab) into a newly-created split group.
 */
export function splitLeafWithSubtree(
  root: PaneNode,
  targetLeafId: string,
  subtree: PaneNode,
  direction: PaneDirection,
  position: "first" | "second" = "second",
  ratio = 0.5,
): PaneNode {
  return mapLeaf(root, targetLeafId, (leaf) => ({
    type: "split",
    direction,
    first: position === "first" ? subtree : leaf,
    second: position === "first" ? leaf : subtree,
    ratio: clampRatio(ratio),
  }));
}

/**
 * Removes the leaf `targetLeafId`, collapsing its parent split into the surviving sibling.
 * Returns `null` when the removed leaf was the whole tree, and the original tree when the
 * leaf does not exist.
 */
export function removeLeaf(root: PaneNode, targetLeafId: string): PaneNode | null {
  if (root.type === "leaf") return root.leafId === targetLeafId ? null : root;

  const first = removeLeaf(root.first, targetLeafId);
  if (first === null) return root.second;
  if (first !== root.first) return { ...root, first };

  const second = removeLeaf(root.second, targetLeafId);
  if (second === null) return root.first;
  if (second !== root.second) return { ...root, second };

  return root;
}

/**
 * Sets the ratio of the split addressed by a dot-notation `path` such as "" (root),
 * "first", or "second.first". Returns the original tree when the path does not resolve
 * to a split node.
 */
export function setRatioAtPath(root: PaneNode, path: string, ratio: number): PaneNode {
  const segments = path.split(".").filter((segment) => segment.length > 0);
  return applyRatio(root, segments, clampRatio(ratio));
}

export function findFirstLeafId(root: PaneNode): string {
  let node = root;
  while (node.type === "split") node = node.first;
  return node.leafId;
}

export function collectLeafIds(root: PaneNode): string[] {
  const ids: string[] = [];
  const visit = (node: PaneNode) => {
    if (node.type === "leaf") {
      ids.push(node.leafId);
      return;
    }
    visit(node.first);
    visit(node.second);
  };
  visit(root);
  return ids;
}

/**
 * Returns the first leaf id inside the sibling subtree of `targetLeafId`,
 * or `null` when the leaf is missing or is the tree root.
 */
export function findSiblingLeafId(root: PaneNode, targetLeafId: string): string | null {
  if (root.type === "leaf") return null;

  const inFirst = containsLeaf(root.first, targetLeafId);
  const inSecond = containsLeaf(root.second, targetLeafId);

  if (inFirst) {
    return root.first.type === "leaf"
      ? findFirstLeafId(root.second)
      : findSiblingLeafId(root.first, targetLeafId);
  }
  if (inSecond) {
    return root.second.type === "leaf"
      ? findFirstLeafId(root.first)
      : findSiblingLeafId(root.second, targetLeafId);
  }
  return null;
}

/**
 * Swaps the positions of two leaves. Returns the original tree when either leaf is
 * missing or when both ids refer to the same leaf.
 */
export function swapLeaves(root: PaneNode, sourceLeafId: string, targetLeafId: string): PaneNode {
  if (sourceLeafId === targetLeafId) return root;
  if (!containsLeaf(root, sourceLeafId) || !containsLeaf(root, targetLeafId)) return root;

  const swap = (node: PaneNode): PaneNode => {
    if (node.type === "leaf") {
      if (node.leafId === sourceLeafId) return { type: "leaf", leafId: targetLeafId };
      if (node.leafId === targetLeafId) return { type: "leaf", leafId: sourceLeafId };
      return node;
    }
    const first = swap(node.first);
    const second = swap(node.second);
    if (first === node.first && second === node.second) return node;
    return { ...node, first, second };
  };

  return swap(root);
}

/** Resets every split in the tree to an even 0.5 ratio. */
export function equalizeRatios(root: PaneNode): PaneNode {
  if (root.type === "leaf") return root;
  const first = equalizeRatios(root.first);
  const second = equalizeRatios(root.second);
  if (first === root.first && second === root.second && root.ratio === 0.5) return root;
  return { ...root, first, second, ratio: 0.5 };
}

function applyRatio(node: PaneNode, segments: string[], ratio: number): PaneNode {
  if (node.type === "leaf") return node;

  if (segments.length === 0) {
    return node.ratio === ratio ? node : { ...node, ratio };
  }

  const [head, ...rest] = segments;
  if (head !== "first" && head !== "second") return node;

  const child = applyRatio(node[head], rest, ratio);
  if (child === node[head]) return node;
  return { ...node, [head]: child };
}

function mapLeaf(node: PaneNode, targetLeafId: string, replace: (leaf: PaneLeafNode) => PaneNode): PaneNode {
  if (node.type === "leaf") return node.leafId === targetLeafId ? replace(node) : node;

  const first = mapLeaf(node.first, targetLeafId, replace);
  if (first !== node.first) return { ...node, first };

  const second = mapLeaf(node.second, targetLeafId, replace);
  if (second !== node.second) return { ...node, second };

  return node;
}

function containsLeaf(node: PaneNode, leafId: string): boolean {
  if (node.type === "leaf") return node.leafId === leafId;
  return containsLeaf(node.first, leafId) || containsLeaf(node.second, leafId);
}

function createLeafId() {
  const randomPart = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `pane:${randomPart}`;
}

import { useCallback, useEffect, useRef, useState } from "react";

import {
  DEFAULT_WORKSPACE_ID,
  isTauriRuntime,
  listWorktrees,
  onWorktreeChanged,
  toIpcError,
} from "../lib/tauri";
import { ensureTerminalEvents } from "../lib/terminalEvents";
import type { StructuredIpcError, Worktree, WorktreeChangedPayload } from "../lib/types";

export type WorkspaceRuntimeServices = {
  ensureTerminalEvents: () => Promise<void>;
  listWorktrees: (workspaceId: string) => Promise<Worktree[]>;
  onWorktreeChanged: (handler: (payload: WorktreeChangedPayload) => void) => Promise<() => void>;
  isTauriRuntime: () => boolean;
};

type UseWorkspaceRuntimeOptions = {
  workspaceId?: string;
  activeWorktreePath: string | null;
  syncWorktrees: (worktrees: Worktree[]) => Promise<void>;
  ensureTabForWorktree: (worktree: Worktree) => Promise<string>;
  services?: WorkspaceRuntimeServices;
};

const defaultServices: WorkspaceRuntimeServices = {
  ensureTerminalEvents,
  listWorktrees,
  onWorktreeChanged,
  isTauriRuntime,
};

const PREVIEW_WORKTREE: Worktree = {
  path: ".",
  head: "main",
  branch: "refs/heads/main",
  bare: false,
  detached: false,
  locked: null,
  prunable: null,
};

export function useWorkspaceRuntime({
  workspaceId = DEFAULT_WORKSPACE_ID,
  activeWorktreePath,
  syncWorktrees,
  ensureTabForWorktree,
  services = defaultServices,
}: UseWorkspaceRuntimeOptions) {
  const [runtimeError, setRuntimeError] = useState<StructuredIpcError | null>(null);
  const activeWorktreePathRef = useRef(activeWorktreePath);
  const refreshInFlightRef = useRef<Promise<void> | null>(null);
  activeWorktreePathRef.current = activeWorktreePath;

  const reportRuntimeError = useCallback((error: unknown) => {
    setRuntimeError(toIpcError(error));
  }, []);

  const refreshWorktrees = useCallback(() => {
    if (refreshInFlightRef.current) return refreshInFlightRef.current;

    const refreshPromise = (async () => {
      try {
        const listed = await services.listWorktrees(workspaceId);
        const worktrees = listed.length > 0 || services.isTauriRuntime() ? listed : [PREVIEW_WORKTREE];
        await syncWorktrees(worktrees);
        const preferred = worktrees.find((worktree) => worktree.path === activeWorktreePathRef.current) ?? worktrees[0];
        if (preferred) await ensureTabForWorktree(preferred);
        setRuntimeError(null);
      } catch (error) {
        reportRuntimeError(error);
      }
    })().finally(() => {
      refreshInFlightRef.current = null;
    });

    refreshInFlightRef.current = refreshPromise;
    return refreshPromise;
  }, [ensureTabForWorktree, reportRuntimeError, services, syncWorktrees, workspaceId]);

  useEffect(() => {
    let disposed = false;
    let unlistenWorktreeChanged: (() => void) | undefined;

    const initialize = async () => {
      await services.ensureTerminalEvents();
      if (disposed) return;
      unlistenWorktreeChanged = await services.onWorktreeChanged(() => {
        void refreshWorktrees();
      });
      if (disposed) {
        unlistenWorktreeChanged();
        return;
      }
      await refreshWorktrees();
    };

    const handleFocus = () => {
      void refreshWorktrees();
    };

    window.addEventListener("focus", handleFocus);
    void initialize().catch(reportRuntimeError);

    return () => {
      disposed = true;
      window.removeEventListener("focus", handleFocus);
      unlistenWorktreeChanged?.();
    };
  }, [refreshWorktrees, reportRuntimeError, services]);

  return { runtimeError, refreshWorktrees, reportRuntimeError };
}

import type { WorkspaceState } from "./workspaceStore";

export type HmrWorkspaceStoreData = {
  workspaceStates?: Record<string, WorkspaceState>;
};

const HMR_REGISTRY_SYMBOL = "__FERRYX_HMR_WORKSPACE_STATES__";

interface GlobalWithHmrRegistry {
  [HMR_REGISTRY_SYMBOL]?: Record<string, WorkspaceState>;
}

function getHmrRegistry(): Record<string, WorkspaceState> | null {
  if (typeof import.meta !== "undefined" && import.meta.env?.DEV) {
    if (typeof window !== "undefined") {
      const globalWindow = window as unknown as GlobalWithHmrRegistry;
      if (!globalWindow[HMR_REGISTRY_SYMBOL]) {
        globalWindow[HMR_REGISTRY_SYMBOL] = {};
      }
      return globalWindow[HMR_REGISTRY_SYMBOL];
    }
    if (typeof globalThis !== "undefined") {
      const globalObject = globalThis as unknown as GlobalWithHmrRegistry;
      if (!globalObject[HMR_REGISTRY_SYMBOL]) {
        globalObject[HMR_REGISTRY_SYMBOL] = {};
      }
      return globalObject[HMR_REGISTRY_SYMBOL];
    }
  }
  return null;
}

export function getHmrWorkspaceState(workspaceId: string): WorkspaceState | null {
  const registry = getHmrRegistry();
  if (registry && registry[workspaceId]) {
    return registry[workspaceId];
  }
  if (typeof import.meta !== "undefined" && import.meta.hot?.data) {
    const hotData = import.meta.hot.data as HmrWorkspaceStoreData | undefined;
    return hotData?.workspaceStates?.[workspaceId] ?? null;
  }
  return null;
}

export function setHmrWorkspaceState(workspaceId: string, state: WorkspaceState): void {
  const registry = getHmrRegistry();
  if (registry) {
    registry[workspaceId] = state;
  }
  if (typeof import.meta !== "undefined" && import.meta.hot?.data) {
    const hotData = import.meta.hot.data as HmrWorkspaceStoreData;
    if (!hotData.workspaceStates) {
      hotData.workspaceStates = {};
    }
    hotData.workspaceStates[workspaceId] = state;
  }
}

export function clearHmrWorkspaceState(workspaceId?: string): void {
  const registry = getHmrRegistry();
  if (registry) {
    if (workspaceId) {
      delete registry[workspaceId];
    } else {
      for (const key of Object.keys(registry)) {
        delete registry[key];
      }
    }
  }
  if (typeof import.meta !== "undefined" && import.meta.hot?.data) {
    const hotData = import.meta.hot.data as HmrWorkspaceStoreData | undefined;
    if (hotData?.workspaceStates) {
      if (workspaceId) {
        delete hotData.workspaceStates[workspaceId];
      } else {
        hotData.workspaceStates = {};
      }
    }
  }
}

if (typeof import.meta !== "undefined" && import.meta.hot) {
  const hotData = import.meta.hot.data as HmrWorkspaceStoreData | undefined;
  if (hotData?.workspaceStates) {
    const registry = getHmrRegistry();
    if (registry) {
      Object.assign(registry, hotData.workspaceStates);
    }
  }
  import.meta.hot.dispose((data: Record<string, unknown>) => {
    const registry = getHmrRegistry();
    if (registry) {
      data.workspaceStates = { ...registry };
    }
  });
}

export const PROJECTS_STORAGE_KEY = "ferryx.projects";
export const ACTIVE_PROJECT_STORAGE_KEY = "ferryx.active-project";
export const SIDEBAR_OPEN_STORAGE_KEY = "ferryx.sidebar.open";
export const SIDEBAR_WIDTH_STORAGE_KEY = "ferryx.sidebar.width";
export const SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY = "ferryx.sidebar.collapsedProjects";
export const TERMINAL_SETTINGS_STORAGE_KEY = "ferryx.terminal.settings";
export const NOTIFICATION_SETTINGS_STORAGE_KEY = "ferryx.settings.notifications:v1";
export const APPEARANCE_SETTINGS_STORAGE_KEY = "ferryx.settings.appearance";
export const BROWSER_SETTINGS_STORAGE_KEY = "ferryx.settings.browser";

export const LEGACY_STORAGE_KEY_MAP: Record<string, string[]> = {
  [PROJECTS_STORAGE_KEY]: ["rorca.projects", "orca.projects"],
  [ACTIVE_PROJECT_STORAGE_KEY]: ["rorca.active-project", "orca.active-project"],
  [SIDEBAR_OPEN_STORAGE_KEY]: ["orca.sidebar.open", "rorca.sidebar.open"],
  [SIDEBAR_WIDTH_STORAGE_KEY]: ["orca.sidebar.width", "rorca.sidebar.width"],
  [SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY]: ["rorca.sidebar.collapsedProjects", "orca.sidebar.collapsedProjects"],
  [TERMINAL_SETTINGS_STORAGE_KEY]: ["orca.terminal.settings", "rorca.terminal.settings"],
  [NOTIFICATION_SETTINGS_STORAGE_KEY]: ["rorca:settings:notifications:v1", "orca:settings:notifications:v1"],
};

export function getMigratedItem(
  key: string,
  storage: Pick<Storage, "getItem" | "setItem"> | null = typeof window !== "undefined" && window.localStorage ? window.localStorage : null,
): string | null {
  if (!storage) return null;
  const value = storage.getItem(key);
  if (value !== null) return value;

  const legacyKeys = LEGACY_STORAGE_KEY_MAP[key] ?? [];
  for (const legacyKey of legacyKeys) {
    const legacyVal = storage.getItem(legacyKey);
    if (legacyVal !== null) {
      try {
        storage.setItem(key, legacyVal);
      } catch {
        // ignore quota or disabled storage error
      }
      return legacyVal;
    }
  }
  return null;
}

export type Unsubscribe = () => void;

export type TerminalAttachment = {
  sessionId: string;
  initialHistory?: Uint8Array;
};

export interface TerminalTransport {
  listSessions(): Promise<{ sessionId: string; worktreePath?: string | null }[]>;
  attach(sessionId: string): Promise<TerminalAttachment>;
  write(sessionId: string, data: string | Uint8Array): Promise<void> | void;
  resize(sessionId: string, cols: number, rows: number): Promise<void> | void;
  signal(sessionId: string, signal: "interrupt" | "terminate" | "kill"): Promise<void> | void;
  close(sessionId: string): Promise<void> | void;
  onOutput(sessionId: string, listener: (data: string | Uint8Array) => void): Unsubscribe;
  onLifecycle(listener: (event: { sessionId: string; state: string; exitCode?: number | null }) => void): Unsubscribe;
}

import type { TerminalAttachment, TerminalTransport, Unsubscribe } from "./types";

export class WebSocketTerminalTransport implements TerminalTransport {
  private baseUrl: string;
  private token: string;
  private sockets: Map<string, WebSocket> = new Map();
  private outputListeners: Map<string, Set<(data: Uint8Array) => void>> = new Map();

  constructor(baseUrl: string, token: string) {
    this.baseUrl = baseUrl.replace(/\/$/, "");
    this.token = token;
  }

  async listSessions() {
    const res = await fetch(`${this.baseUrl}/api/v1/sessions?token=${encodeURIComponent(this.token)}`);
    if (!res.ok) throw new Error(`Failed to list sessions: ${res.statusText}`);
    const data = await res.json();
    return data.map((s: { sessionId: string }) => ({ sessionId: s.sessionId }));
  }

  async attach(sessionId: string): Promise<TerminalAttachment> {
    const wsProto = this.baseUrl.startsWith("https") ? "wss" : "ws";
    const host = this.baseUrl.replace(/^https?:\/\//, "");
    const wsUrl = `${wsProto}://${host}/api/v1/terminal/${sessionId}?token=${encodeURIComponent(this.token)}`;

    const ws = new WebSocket(wsUrl);
    ws.binaryType = "arraybuffer";

    const listeners = this.outputListeners.get(sessionId) ?? new Set();
    this.outputListeners.set(sessionId, listeners);

    ws.onmessage = (event) => {
      let data: Uint8Array;
      if (typeof event.data === "string") {
        data = new TextEncoder().encode(event.data);
      } else {
        data = new Uint8Array(event.data);
      }
      for (const listener of listeners) {
        listener(data);
      }
    };

    this.sockets.set(sessionId, ws);
    return { sessionId };
  }

  write(sessionId: string, data: string | Uint8Array) {
    const ws = this.sockets.get(sessionId);
    if (!ws || ws.readyState !== WebSocket.OPEN) return;
    const bytes = typeof data === "string" ? new TextEncoder().encode(data) : data;
    ws.send(bytes);
  }

  resize(sessionId: string, cols: number, rows: number) {
    const ws = this.sockets.get(sessionId);
    if (!ws || ws.readyState !== WebSocket.OPEN) return;
    ws.send(JSON.stringify({ type: "resize", cols, rows }));
  }

  signal(sessionId: string, signal: "interrupt" | "terminate" | "kill") {
    const ws = this.sockets.get(sessionId);
    if (!ws || ws.readyState !== WebSocket.OPEN) return;
    ws.send(JSON.stringify({ type: "signal", signal }));
  }

  async close(sessionId: string) {
    const ws = this.sockets.get(sessionId);
    if (ws) {
      ws.close();
      this.sockets.delete(sessionId);
    }
  }

  onOutput(sessionId: string, listener: (data: string | Uint8Array) => void): Unsubscribe {
    const listeners = this.outputListeners.get(sessionId) ?? new Set();
    const wrapped = (bytes: Uint8Array) => listener(bytes);
    listeners.add(wrapped);
    this.outputListeners.set(sessionId, listeners);

    return () => {
      listeners.delete(wrapped);
    };
  }

  onLifecycle(_listener: (event: { sessionId: string; state: string; exitCode?: number | null }) => void): Unsubscribe {
    return () => {};
  }
}

import {
  closeTerminal,
  listTerminalSessions,
  onTerminalLifecycle,
  onTerminalOutput,
  resizeTerminal,
  signalTerminal,
  writeTerminal,
} from "../tauri";
import type { TerminalAttachment, TerminalTransport, Unsubscribe } from "./types";

export class TauriTerminalTransport implements TerminalTransport {
  async listSessions() {
    const sessions = await listTerminalSessions();
    return sessions.map((s) => ({
      sessionId: s.sessionId,
      worktreePath: s.worktreePath,
    }));
  }

  async attach(sessionId: string): Promise<TerminalAttachment> {
    return { sessionId };
  }

  async write(sessionId: string, data: string | Uint8Array) {
    const text = typeof data === "string" ? data : new TextDecoder().decode(data);
    await writeTerminal({ sessionId, data: text });
  }

  async resize(sessionId: string, cols: number, rows: number) {
    await resizeTerminal({ sessionId, cols, rows });
  }

  async signal(sessionId: string, signal: "interrupt" | "terminate" | "kill") {
    await signalTerminal({ sessionId, signal });
  }

  async close(sessionId: string) {
    await closeTerminal(sessionId);
  }

  onOutput(sessionId: string, listener: (data: string | Uint8Array) => void): Unsubscribe {
    let unlisten: (() => void) | null = null;
    let cancelled = false;

    onTerminalOutput((payload) => {
      if (payload.sessionId === sessionId) {
        listener(payload.data);
      }
    }).then((fn) => {
      if (cancelled) {
        fn();
      } else {
        unlisten = fn;
      }
    });

    return () => {
      cancelled = true;
      if (unlisten) {
        unlisten();
      }
    };
  }

  onLifecycle(listener: (event: { sessionId: string; state: string; exitCode?: number | null }) => void): Unsubscribe {
    let unlisten: (() => void) | null = null;
    let cancelled = false;

    onTerminalLifecycle((payload) => {
      listener({
        sessionId: payload.sessionId,
        state: payload.state,
        exitCode: payload.exitCode,
      });
    }).then((fn) => {
      if (cancelled) {
        fn();
      } else {
        unlisten = fn;
      }
    });

    return () => {
      cancelled = true;
      if (unlisten) {
        unlisten();
      }
    };
  }
}

export const defaultTauriTransport = new TauriTerminalTransport();

import type { Terminal } from "@xterm/xterm";

import { terminalEventBus } from "./terminalEvents";

export const MAX_PENDING_OUTPUT_CHARS = 128 * 1024;

/**
 * Batches incoming PTY output chunks per terminal renderer at animation-frame cadence.
 *
 * Queue policy:
 * - Chunks received between rAF flushes are held in an ordered per-renderer buffer.
 * - On frame flush, all buffered chunks coalesce into a single `terminal.write` call in original arrival order.
 * - If queued characters reach or exceed `MAX_PENDING_OUTPUT_CHARS` before rAF, the buffer is flushed synchronously
 *   to guarantee memory safety without loss or reordering.
 * - Replay backlog delivered synchronously during `subscribeOutput` is enqueued before subsequent live output.
 * - Teardown (via unlisten or manager destroy) immediately cancels pending rAF callbacks and clears buffered data,
 *   preventing stale or out-of-order writes after session rebinding or instance disposal.
 */
export function attachScheduledOutputSubscription(
  backendSessionId: string,
  terminal: Terminal,
): () => void {
  let outputBuffer: string[] = [];
  let outputBufferChars = 0;
  let outputFrame = 0;

  const flushOutput = () => {
    if (outputFrame !== 0) {
      cancelAnimationFrame(outputFrame);
      outputFrame = 0;
    }
    if (outputBuffer.length === 0) return;
    const coalesced = outputBuffer.length === 1 ? (outputBuffer[0] ?? "") : outputBuffer.join("");
    outputBuffer = [];
    outputBufferChars = 0;
    terminal.write(coalesced);
  };

  const unsubscribe = terminalEventBus.subscribeOutput(backendSessionId, (text) => {
    outputBuffer.push(text);
    outputBufferChars += text.length;

    if (outputBufferChars >= MAX_PENDING_OUTPUT_CHARS) {
      flushOutput();
    } else if (outputFrame === 0) {
      outputFrame = requestAnimationFrame(flushOutput);
    }
  });

  return () => {
    if (outputFrame !== 0) {
      cancelAnimationFrame(outputFrame);
      outputFrame = 0;
    }
    outputBuffer = [];
    outputBufferChars = 0;
    unsubscribe();
  };
}

import type { TerminalLifecyclePayload, TerminalOutputPayload } from "./types";
import { onTerminalLifecycle, onTerminalOutput } from "./tauri";
import { TerminalOutputDecoderRegistry } from "./terminalOutput";

const MAX_BACKLOG_CHARS = 512 * 1024;
const MAX_OSC_TITLE_CHARS = 8 * 1024;
const OSC_TITLE_START_RE = /\u001b\](?:0|1|2);/g;
const OSC_PARTIAL_PREFIXES = ["\u001b", "\u001b]", "\u001b]0", "\u001b]1", "\u001b]2"] as const;

type OutputListener = (text: string) => void;
type LifecycleListener = (payload: TerminalLifecyclePayload) => void;
type TitleListener = (sessionId: string, title: string) => void;

type SessionBacklog = {
  chunks: string[];
  totalChars: number;
};

export type OscTitleScanResult = {
  titles: string[];
  carry: string;
};

/**
 * Extracts OSC 0/1/2 terminal titles from decoded PTY output while preserving an incomplete
 * sequence for the next chunk. This runs independently of xterm, so background/unmounted tabs
 * still produce activity title updates.
 */
export function scanTerminalOscTitles(text: string, carry = ""): OscTitleScanResult {
  const source = `${carry}${text}`;
  const titles: string[] = [];
  let searchFrom = 0;

  OSC_TITLE_START_RE.lastIndex = 0;
  while (true) {
    OSC_TITLE_START_RE.lastIndex = searchFrom;
    const match = OSC_TITLE_START_RE.exec(source);
    if (!match) break;

    const valueStart = match.index + match[0].length;
    const terminator = findOscTerminator(source, valueStart);
    if (!terminator) {
      return {
        titles,
        carry: source.slice(Math.max(match.index, source.length - MAX_OSC_TITLE_CHARS)),
      };
    }

    titles.push(source.slice(valueStart, terminator.index));
    searchFrom = terminator.index + terminator.length;
  }

  return { titles, carry: findPartialOscPrefix(source.slice(searchFrom)) };
}

function findOscTerminator(source: string, from: number): { index: number; length: number } | null {
  const candidates = [
    { index: source.indexOf("\u0007", from), length: 1 },
    { index: source.indexOf("\u001b\\", from), length: 2 },
    { index: source.indexOf("\u009c", from), length: 1 },
  ].filter((candidate) => candidate.index >= 0);
  if (candidates.length === 0) return null;
  return candidates.reduce((earliest, candidate) => candidate.index < earliest.index ? candidate : earliest);
}

function findPartialOscPrefix(source: string): string {
  for (const prefix of [...OSC_PARTIAL_PREFIXES].sort((a, b) => b.length - a.length)) {
    if (source.endsWith(prefix)) return prefix;
  }
  return "";
}

class TerminalEventBus {
  private readonly decoderRegistry = new TerminalOutputDecoderRegistry();
  private readonly outputListeners = new Map<string, Set<OutputListener>>();
  private readonly lifecycleListeners = new Set<LifecycleListener>();
  private readonly titleListeners = new Set<TitleListener>();
  private readonly backlog = new Map<string, SessionBacklog>();
  private readonly titleCarry = new Map<string, string>();
  private readonly lastTitle = new Map<string, string>();
  private startPromise: Promise<void> | null = null;

  ensureStarted(): Promise<void> {
    if (this.startPromise) return this.startPromise;
    this.startPromise = Promise.all([
      onTerminalOutput((payload) => this.handleOutput(payload)),
      onTerminalLifecycle((payload) => this.handleLifecycle(payload)),
    ]).then(() => undefined);
    return this.startPromise;
  }

  subscribeOutput(sessionId: string, listener: OutputListener, replay = true) {
    const listeners = this.outputListeners.get(sessionId) ?? new Set<OutputListener>();
    listeners.add(listener);
    this.outputListeners.set(sessionId, listeners);

    if (replay) {
      const existing = this.backlog.get(sessionId);
      if (existing && existing.totalChars > 0) {
        listener(existing.chunks.join(""));
      }
    }

    return () => {
      const current = this.outputListeners.get(sessionId);
      current?.delete(listener);
      if (current?.size === 0) this.outputListeners.delete(sessionId);
    };
  }

  subscribeLifecycle(listener: LifecycleListener) {
    this.lifecycleListeners.add(listener);
    return () => {
      this.lifecycleListeners.delete(listener);
    };
  }

  subscribeTitle(listener: TitleListener) {
    this.titleListeners.add(listener);
    return () => {
      this.titleListeners.delete(listener);
    };
  }

  clearSession(sessionId: string) {
    this.decoderRegistry.reset(sessionId);
    this.backlog.delete(sessionId);
    this.outputListeners.delete(sessionId);
    this.titleCarry.delete(sessionId);
    this.lastTitle.delete(sessionId);
  }

  getBacklogMetricsForTest(sessionId?: string): { sessions: number; chunks: number; chars: number } {
    if (sessionId) {
      const entry = this.backlog.get(sessionId);
      if (!entry) return { sessions: 0, chunks: 0, chars: 0 };
      return {
        sessions: 1,
        chunks: entry.chunks.length,
        chars: entry.totalChars,
      };
    }
    let totalChunks = 0;
    let totalChars = 0;
    for (const entry of this.backlog.values()) {
      totalChunks += entry.chunks.length;
      totalChars += entry.totalChars;
    }
    return {
      sessions: this.backlog.size,
      chunks: totalChunks,
      chars: totalChars,
    };
  }

  private handleOutput(payload: TerminalOutputPayload) {
    const text = this.decoderRegistry.decode(payload.sessionId, payload.data);
    if (text) this.publishOutput(payload.sessionId, text);
  }

  private handleLifecycle(payload: TerminalLifecyclePayload) {
    if (payload.state === "exited" || payload.state === "failed") {
      const tail = this.decoderRegistry.finish(payload.sessionId);
      if (tail) this.publishOutput(payload.sessionId, tail);
    }
    for (const listener of this.lifecycleListeners) listener(payload);
  }

  private publishOutput(sessionId: string, text: string) {
    const scan = scanTerminalOscTitles(text, this.titleCarry.get(sessionId) ?? "");
    if (scan.carry) this.titleCarry.set(sessionId, scan.carry);
    else this.titleCarry.delete(sessionId);

    for (const title of scan.titles) {
      if (this.lastTitle.get(sessionId) === title) continue;
      this.lastTitle.set(sessionId, title);
      for (const listener of this.titleListeners) listener(sessionId, title);
    }

    if (text.length > 0) {
      let entry = this.backlog.get(sessionId);
      if (!entry) {
        entry = { chunks: [], totalChars: 0 };
        this.backlog.set(sessionId, entry);
      }

      entry.chunks.push(text);
      entry.totalChars += text.length;

      while (entry.totalChars > MAX_BACKLOG_CHARS && entry.chunks.length > 0) {
        const oldest = entry.chunks[0];
        if (oldest === undefined) break;
        const overflow = entry.totalChars - MAX_BACKLOG_CHARS;
        if (oldest.length <= overflow) {
          entry.chunks.shift();
          entry.totalChars -= oldest.length;
        } else {
          entry.chunks[0] = oldest.slice(overflow);
          entry.totalChars -= overflow;
          break;
        }
      }
    }

    for (const listener of this.outputListeners.get(sessionId) ?? []) listener(text);
  }
}

export const terminalEventBus = new TerminalEventBus();

